<script>(function(){const h=document.documentElement,b=document.getElementById('dvThemeBtn'),i=document.getElementById('dvThemeIcon'),s=localStorage.getItem('dvsser-theme')||'dark';function set(t){h.setAttribute('data-theme',t);i.className=t==='dark'?'bi bi-sun':'bi bi-moon-stars'}set(s);b.addEventListener('click',()=>{const t=h.getAttribute('data-theme')==='dark'?'light':'dark';localStorage.setItem('dvsser-theme',t);set(t)});document.getElementById('dvYear').textContent=new Date().getFullYear();const side=document.getElementById('dvSidebar'),over=document.getElementById('dvOverlay');document.getElementById('dvHamburger').addEventListener('click',()=>{side.classList.toggle('open');over.classList.toggle('open')});over.addEventListener('click',()=>{side.classList.remove('open');over.classList.remove('open')})})();</script></body></html>
